<?php $__empty_1 = true; $__currentLoopData = $orders; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $o): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="ec-row"><div><strong><?php echo e($o->order_no); ?></strong><p class="ec-muted"><?php echo e($o->created_at?->format('d M Y')); ?> · ৳<?php echo e(number_format($o->total,2)); ?></p></div><div><?php echo $__env->make('public.business.public.ecommerce.account.status',['status'=>$o->status==='confirmed'?$o->delivery_status:$o->status], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?></div><a class="ec-btn" href="<?php echo e(route('business.customer.orders.show',['order'=>$o->id])); ?>"><?php echo e(t('Details','বিবরণ')); ?> →</a></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><p><?php echo e(t('No orders yet.','এখনো কোনো অর্ডার নেই।')); ?></p><a class="ec-btn" href="<?php echo e(route('business.customer.shop')); ?>"><?php echo e(t('Start shopping','কেনাকাটা করুন')); ?></a><?php endif; ?>
